using System;using System.Collections;using System.IO;using System.Linq;
using NUnit.Framework;using LegendsOfRus.GameplayCore;using UnityEngine;
namespace LegendsOfRus.Tests {
public class MechanicsInteractionRulesTests {
 static BoardPosition P(int x,int y)=>new BoardPosition(x,y);
 static BoardModel Board(){var b=new BoardModel(8,7,6,new SeededBoardRandom(1)){SquareMatches=true,StandaloneSpecials=true};for(int y=0;y<7;y++)for(int x=0;x<8;x++)b.SetCell(P(x,y),new BoardCellData((x+2*y)%5));return b;}
 static BoardResolutionPlanner Planner(BoardModel b)=>new BoardResolutionPlanner(b,null,GameplayRuleVersion.PrototypeR4);
 [TestCase(SpecialGemKind.Row)][TestCase(SpecialGemKind.Column)][TestCase(SpecialGemKind.Burst)][TestCase(SpecialGemKind.Spark)][TestCase(SpecialGemKind.Color)]
 public void TapAndBothDragDirectionsResolveWithoutOrdinaryMatch(SpecialGemKind kind){
  foreach(bool reverse in new[]{false,true}){var b=Board();var a=P(3,3);var c=P(4,3);b.SetCell(a,new BoardCellData(5,kind));string hash=b.ComputeStateHash();Assert.That(b.FindRuns(),Is.Empty);var p=Planner(b).PlanSwap(reverse?c:a,reverse?a:c);Assert.That(p.IsResolved,Is.True);Assert.That(p.ConsumesMove,Is.True);Assert.That(b.ComputeStateHash(),Is.EqualTo(hash));Assert.That(p.Waves[0].Activations.Any(x=>x.Kind==kind && x.Position==c),Is.True);Assert.That(Planner(b).PlanTapSpecial(a).IsResolved,Is.True);}
 }
 [TestCase(SpecialGemKind.Row,0,1)][TestCase(SpecialGemKind.Column,1,0)]
 public void MovedOrdinaryGemSurvivesOutsideLineFootprint(SpecialGemKind kind,int dx,int dy){var b=Board();var a=P(3,3);var c=P(3+dx,3+dy);int color=b.GetTile(c);b.SetCell(a,new BoardCellData(5,kind));var w=Planner(b).PlanSwap(a,c).Waves[0];Assert.That(w.ClearedCells.Any(x=>x.Position==a),Is.False);Assert.That(w.SnapshotAfterClear.Tiles[a.Y*8+a.X],Is.EqualTo(color));}
 [TestCase(BoardObstacleKind.Chain)][TestCase(BoardObstacleKind.Crate)][TestCase(BoardObstacleKind.RunicSeal)]
 public void BlockedDestinationAndBlockedSourceDoNotSpend(BoardObstacleKind kind){foreach(bool source in new[]{false,true}){var b=Board();var a=P(3,3);var c=P(4,3);b.SetCell(a,new BoardCellData(5,SpecialGemKind.Burst));b.SetObstacle(source?a:c,new BoardObstacleData(kind,2));var p=Planner(b).PlanSwap(a,c);Assert.That(p.IsResolved,Is.False);Assert.That(p.ConsumesMove,Is.False);Assert.That(p.FinalSnapshot.StateHash,Is.EqualTo(b.ComputeStateHash()));}}
 [Test] public void SpecialsCannotBridgeLinesOrSquaresAndCanStillChain(){
 var b=Board();foreach(var p in new[]{P(1,2),P(2,2),P(3,2),P(1,3),P(2,3)})b.SetCell(p,new BoardCellData(5));b.SetCell(P(2,2),new BoardCellData(5,SpecialGemKind.Burst));Assert.That(b.FindRuns(),Is.Empty);b.StandaloneSpecials=false;Assert.That(b.FindRuns(),Is.Not.Empty);b.StandaloneSpecials=true;b.SetCell(P(2,3),new BoardCellData(5,SpecialGemKind.Row));Assert.That(Planner(b).PlanTapSpecial(P(2,2)).Waves[0].Activations.Any(a=>a.Kind==SpecialGemKind.Row),Is.True);}
 [TestCase(SpecialGemKind.Row)][TestCase(SpecialGemKind.Column)][TestCase(SpecialGemKind.Burst)][TestCase(SpecialGemKind.Spark)]
 public void RainbowCombinesMostCommonOrdinaryColorInBothDirections(SpecialGemKind partner){foreach(bool reverse in new[]{false,true}){var b=Board();b.SetCell(P(3,3),new BoardCellData(4,SpecialGemKind.Color));b.SetCell(P(4,3),new BoardCellData(5,partner));var w=Planner(b).PlanSwap(reverse?P(4,3):P(3,3),reverse?P(3,3):P(4,3)).Waves[0];var forced=w.Activations.Where(a=>a.Kind==partner&&a.ForcedByCombination).ToArray();Assert.That(forced.Length,Is.EqualTo(12));Assert.That(forced.All(a=>a.TileType==2),Is.True);Assert.That(forced.All(a=>a.Position!=P(3,3)&&a.Position!=P(4,3)),Is.True);}}
 [Test] public void RainbowTapExcludesHiddenSpecialColorsAndTiesUseLowestId(){var b=new BoardModel(4,4,6,new SeededBoardRandom(1)){SquareMatches=true,StandaloneSpecials=true};for(int y=0;y<4;y++)for(int x=0;x<4;x++)b.SetCell(P(x,y),new BoardCellData(5,SpecialGemKind.Burst));b.SetCell(P(0,0),new BoardCellData(5,SpecialGemKind.Color));b.SetCell(P(1,0),new BoardCellData(1));b.SetCell(P(2,0),new BoardCellData(2));var w=Planner(b).PlanTapSpecial(P(0,0)).Waves[0];Assert.That(w.Activations.Single().TileType,Is.EqualTo(1));Assert.That(w.ClearedCells.Count,Is.EqualTo(2));}
 [Test] public void RainbowNormalSwapStillUsesSelectedColor(){var b=Board();b.SetCell(P(3,3),new BoardCellData(5,SpecialGemKind.Color));b.SetCell(P(4,3),new BoardCellData(3));var w=Planner(b).PlanSwap(P(3,3),P(4,3)).Waves[0];Assert.That(w.Activations.Single().TileType,Is.EqualTo(3));Assert.That(w.ClearedCells.All(c=>c.Cell.Special==SpecialGemKind.Color||c.Cell.TileType==3),Is.True);}
 [Test] public void NoOrdinaryColorConsumesSourcesWithoutPhantomPayload(){var b=new BoardModel(3,3,6,new SeededBoardRandom(1)){SquareMatches=true,StandaloneSpecials=true};b.SetCell(P(0,0),new BoardCellData(5,SpecialGemKind.Color));b.SetCell(P(1,0),new BoardCellData(5,SpecialGemKind.Spark));var p=Planner(b).PlanSwap(P(0,0),P(1,0));Assert.That(p.IsResolved,Is.True);Assert.That(p.Waves[0].Activations,Is.Empty);Assert.That(p.Waves[0].ClearedCells.Count,Is.EqualTo(2));}
 [Test] public void HiddenColorDoesNotCountTowardsOrdinaryGemGoals(){var b=Board();b.SetCell(P(3,3),new BoardCellData(5,SpecialGemKind.Burst));var w=Planner(b).PlanTapSpecial(P(3,3)).Waves[0];Assert.That(w.ClearedByTileType[5],Is.Zero);}
 public static IEnumerable Pairs(){var kinds=new[]{SpecialGemKind.Row,SpecialGemKind.Column,SpecialGemKind.Burst,SpecialGemKind.Spark,SpecialGemKind.Color};for(int i=0;i<5;i++)for(int j=i;j<5;j++)yield return new TestCaseData(kinds[i],kinds[j]);}
 [TestCaseSource(nameof(Pairs))] public void AllPairsResolveDeterministicallyAndReplay(SpecialGemKind a,SpecialGemKind c){foreach(bool reverse in new[]{false,true}){var b=Board();b.SetCell(P(3,3),new BoardCellData(5,a));b.SetCell(P(4,3),new BoardCellData(4,c));var cmd=new MechanicsReplayCommand{Rules=GameplayRuleVersion.PrototypeR4,BeforeToken=b.CreateSnapshot().ToReplayToken(),X=reverse?4:3,Y=3,ToX=reverse?3:4,ToY=3};var p=cmd.Resolve();Assert.That(p.IsResolved&&p.ConsumesMove,Is.True);cmd.ExpectedPlanHash=p.PlanHash;Assert.That(cmd.Resolve().FinalSnapshot.StateHash,Is.EqualTo(p.FinalSnapshot.StateHash));}}
 [Test] public void EdgeBlastAndSealDamageKeepExistingBudgets(){var b=Board();b.SetCell(P(0,0),new BoardCellData(5,SpecialGemKind.Burst));b.SetObstacle(P(1,1),new BoardObstacleData(BoardObstacleKind.RunicSeal,2));var w=Planner(b).PlanTapSpecial(P(0,0)).Waves[0];Assert.That(w.ClearedCells.Count,Is.EqualTo(8));Assert.That(w.ObstacleInteractions.Single().LayersAfter,Is.EqualTo(1));}
 [Test] public void StandaloneSpecialRemainsLegalActionWithoutColorMatch(){var b=Board();b.SetCell(P(0,0),new BoardCellData(5,SpecialGemKind.Column));Assert.That(b.TryFindLegalAction(out var a,out var c),Is.True);Assert.That(a,Is.EqualTo(c));Assert.That(Planner(b).PlanTapSpecial(a).IsResolved,Is.True);}
 [TestCase(false)][TestCase(true)] public void FourAndSquareFormationStillWork(bool square){var b=Board();foreach(var p in square?new[]{P(2,2),P(3,2),P(2,3),P(3,3)}:new[]{P(1,2),P(2,2),P(3,2),P(4,2)})b.SetCell(p,new BoardCellData(5));var made=b.DetermineSpecialCreations(b.FindRuns(),P(3,2),true);Assert.That(made.Single().Value,Is.EqualTo(square?SpecialGemKind.Spark:SpecialGemKind.Column));Assert.That(made.Single().Key,Is.EqualTo(P(3,2)));}
 [Test] public void Existing244PlanAndStateHashesStayExact(){var file=Path.Combine(Application.dataPath,"../ProjectDocs/AI/GameplayMechanics/R12/QA/LegacyGolden.tsv");var rows=File.ReadAllLines(file);Assert.That(rows.Length,Is.EqualTo(244));foreach(var row in rows){var f=row.Split('\t');var cmd=new MechanicsReplayCommand{Rules=(GameplayRuleVersion)int.Parse(f[0]),X=int.Parse(f[1]),Y=3,ToX=int.Parse(f[2]),ToY=3,BeforeToken=f[3],ExpectedPlanHash=f[4]};Assert.That(cmd.Resolve().FinalSnapshot.StateHash,Is.EqualTo(f[5]));}}
}}
